<script setup lang="ts">
import {computed,ref} from 'vue'
import TeachingContent from '../../courses/components/TeachingContent.vue'
import RestartEnglishStudy from './RestartEnglishStudy.vue'
import {engineCall} from '../../../shared/api'
import {navigate,makeRequestKey,reportError,notify} from '../../../shared/ui'
import type {CourseDetailData,CourseStudyDetailData} from '../../../shared/api/contracts'
const props=defineProps<{data:CourseDetailData;planLineId?:string}>()
const busy=ref(false)
const count=computed(()=>props.data.lessons.reduce((n,l)=>n+l.exercises.length,0))
const sourceChanged=computed(()=>props.data.course.source_changed===true)
async function start(newRound=false){if(busy.value||(newRound&&props.data.course.can_start_new_round===false))return;busy.value=true;try{const opened=await engineCall<CourseStudyDetailData>('course.study.open',{course_id:props.data.course.id,idempotency_key:makeRequestKey('english-open'),review_round:newRound&&!sourceChanged.value,new_version:newRound&&sourceChanged.value,...(props.planLineId?{plan_line_id:props.planLineId}:{})});if((opened as CourseStudyDetailData & {scope_notice?:string}).scope_notice)notify((opened as CourseStudyDetailData & {scope_notice:string}).scope_notice,'info');await navigate('/english/'+opened.study.id)}catch(e){reportError(e)}finally{busy.value=false}}
</script>
<template><section class="english-overview"><button class="back-button" @click="navigate((planLineId||data.course.plan_line_id)?'/plan/'+(planLineId||data.course.plan_line_id):'/plans')">← 返回学习计划</button><span class="english-kicker">ENGLISH · 词句训练</span><h2>{{data.course.title}}</h2><p class="english-intro">{{data.course.summary}}</p><div class="english-course-meta"><span>{{data.lessons.length}} 个训练组</span><span>{{count}} 个训练项</span><span>本地保存 · 随时继续</span></div><div class="english-overview-actions"><button class="primary-button" :disabled="busy" @click="start()">{{busy?'正在恢复…':'开始 / 继续训练 →'}}</button><button v-if="data.course.study_session_id" class="text-button" :disabled="busy||data.course.can_start_new_round===false" @click="start(true)">{{sourceChanged?'学习修订后的课程':'开启新的回顾轮次'}}</button></div><RestartEnglishStudy v-if="data.course.study_session_id&&data.course.can_start_new_round===false" :study-id="data.course.study_session_id" :workspace-key="data.workspace_key||data.course.id" :course-id="data.course.id"/><p v-if="sourceChanged" class="english-assistance" role="status">课程内容已更新，学习进度已重置。开始 / 继续训练将使用最新版本（{{count}} 项）；上一轮已收口保留为历史。</p><p v-if="data.course.study_session_id&&data.course.can_start_new_round===false" class="english-assistance" role="status">{{data.course.new_round_blocker}}</p><p v-else-if="data.course.waiting_count" class="english-assistance" role="status">本轮训练已提交，另有 {{data.course.waiting_count}} 项旧记录待审核。主动开启下一轮不会覆盖旧答案，也不会把待审核判为通过。</p><ol class="english-group-list"><li v-for="lesson in data.lessons" :key="lesson.id"><div><h3>{{lesson.title}}</h3><p>{{lesson.exercises.length}} 个训练项</p></div><span>{{lesson.exercises.map(x=>x.title).slice(0,3).join(' · ')}}</span><details v-if="lesson.content_blocks?.length" class="english-overview-teaching"><summary>阅读本组讲解</summary><TeachingContent :blocks="lesson.content_blocks.filter(b=>b.type!=='practice')" :exercises="lesson.exercises" :notes="[]" study-id="" :lesson-id="lesson.id" :blocked="true" :preference-scope="(data.workspace_key||data.course.id)+':preview:'+data.course.content_revision"/></details></li></ol><p class="muted">词典发音需要网络；不可用时仍可完成文字训练。课程完成与长期掌握分开记录。</p></section></template>
